GRANT SELECT,INSERT ON firstten_policy_test.consent_ack TO authenticated;
CREATE FUNCTION firstten_policy_test.choice(kind text,target uuid,note text,ai text,sharing text,revision bigint) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog,public,firstten_policy_test AS $$ SELECT public.set_processing_consent(firstten_policy_test.id('consent_project'),kind,target,note,ai,sharing,1,revision); $$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.choice(text,uuid,text,text,text,bigint) TO authenticated;
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.processing_consents'::regclass),'consent RLS enabled');
