-- A mid-transaction permission-persistence fault must roll back the inserted interview.
CREATE FUNCTION firstten_policy_test.capture_consent_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('firstten.capture_consent_fault',true)='on' AND NEW.target_kind='interview' THEN RAISE EXCEPTION 'Intentional consent persistence failure'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER prv001_capture_fault BEFORE INSERT ON public.processing_consents FOR EACH ROW EXECUTE FUNCTION firstten_policy_test.capture_consent_fault();
SELECT set_config('firstten.capture_consent_fault','on',true);
SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_interview_with_consent(firstten_policy_test.id('consent_project'),firstten_policy_test.id('consent_contact'),'[{"q":"Recent event?","note":"ATOMIC_SENTINEL","quote":""}]','{}','granted','unknown','unknown',1,'fa110000-0000-4000-8000-000000000012')$$,'P0001','Intentional consent persistence failure','permission persistence error aborts the whole capture');
SELECT is((SELECT count(*) FROM public.interviews WHERE project_id=firstten_policy_test.id('consent_project')),2::bigint,'failed permission write leaves no inserted interview');
RESET ROLE;
SELECT is((SELECT count(*) FROM firstten_private.interview_capture_operations WHERE request_id='fa110000-0000-4000-8000-000000000012'),0::bigint,'failed capture leaves no acknowledgement journal');
SELECT set_config('firstten.capture_consent_fault','off',true);
DROP TRIGGER prv001_capture_fault ON public.processing_consents;
